const copy={runtime:['Remote runtime connection checklist',['Confirm the runtime is cloud-hosted and independent of your Mac.','Record the service URL, owner, region, and a read-only health endpoint.','Set a heartbeat interval and a missed-heartbeat threshold.','Send a signed test heartbeat; keep its timestamp and response as evidence.']],scheduler:['Scheduler verification checklist',['List every autonomous task with its trigger, owner, timeout, and retry ceiling.','Run one harmless diagnostic task and retain its start, finish, and result.','Confirm task history survives a restart of the service.','Do not enable remediation tasks until the approval gate is configured.']],notification:['Notification delivery checklist',['Choose the destination channel and confirm the recipient identity.','Send a test with a unique reference code.','Require a delivery receipt or an equivalent provider status; “sent” is insufficient.','Record the receipt and test time in the evidence ledger.']],approval:['Production action approval gate',['Capture the failure evidence and exact affected service.','Write the proposed action, expected impact, and rollback procedure.','Request explicit approval before restarting, redeploying, or changing configuration.','After the action, run the same health and delivery checks again.']]};
const modal=document.querySelector('#modal');document.querySelectorAll('[data-modal]').forEach(b=>b.addEventListener('click',()=>{const [title,items]=copy[b.dataset.modal];document.querySelector('#modal-title').textContent=title;document.querySelector('#modal-body').innerHTML='<ul>'+items.map(i=>'<li>'+i+'</li>').join('')+'</ul>';modal.showModal()}));document.querySelector('#close-modal').addEventListener('click',()=>modal.close());document.querySelectorAll('[data-scroll]').forEach(b=>b.addEventListener('click',()=>document.querySelector('#'+b.dataset.scroll).scrollIntoView()));
